pug:
table.sys-footer--box(role="presentation" width="100%" style="background-color:{{ background_color }};border-radius:{{ radius }}")
    tr
        td.sys-footer--pad(align="center" style="padding:{{ padding }};text-align:center")
            table.sys-footer--inner(role="presentation" width="100%")
                tr
                    td(align="center" style="text-align:center")
                        p.sys-footer--small(style="color:{{ text_color }}") {{ company_address }}
                        p.sys-footer--small.sys-footer--gap(style="color:{{ text_color }}") {{ risk_warning }}
                        p.sys-footer--links
                            a.sys-footer--link(href="{{ terms_href }}" universal="true" target="_blank" style="color:{{ link_color }}") {{ conditions }}
                            span.sys-footer--sep(style="color:{{ link_color }}") &nbsp;|&nbsp;
                            a.sys-footer--link(href="{{ unsubscribe_href }}" universal="true" target="_blank" style="color:{{ link_color }}") {{ unsubscribe }}
